  1→import {
  2→  useCallback,
  3→  useRef,
  4→  useState,
  5→  type ReactNode,
  6→} from 'react';
  7→import { AgentContext } from '../hooks/useAgent';
  8→import { runAgentLoop, runAgentEditLoop } from '../agent/agentService';
  9→import type { ChatMessage, ContentSegment, ToolCallResult } from '../types';
 10→import { useSessionId } from '../hooks/useSessionId';
 11→import { generateUUID } from '../utils/uuid';
 12→
 13→function generateId() {
 14→  return generateUUID();
 15→}
 16→
 17→export function AgentProvider({
 18→  children,
 19→  refreshTables,
 20→}: {
 21→  children: ReactNode;
 22→  refreshTables: () => Promise<void>;
 23→}) {
 24→  const userSessionId = useSessionId();
 25→  const [messages, setMessages] = useState<ChatMessage[]>([]);
 26→  const [isStreaming, setIsStreaming] = useState(false);
 27→  const abortRef = useRef<AbortController | null>(null);
 28→  const textBufferRef = useRef('');
 29→  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
 30→  const assistantIdRef = useRef('');
 31→  const segmentsRef = useRef<ContentSegment[]>([]);
 32→  const currentTextRef = useRef('');
 33→  const phaseRef = useRef<'thinking' | 'answer'>('thinking');
 34→  const sessionIdRef = useRef<string | null>(null);
 35→  const pendingHistoryRef = useRef<{ role: string; content: string }[] | null>(null);
 36→
 37→  const flushText = useCallback(() => {
 38→    const text = textBufferRef.current;
 39→    if (!text) return;
 40→    const id = assistantIdRef.current;
 41→    currentTextRef.current += text;
 42→    setMessages((prev) =>
 43→      prev.map((m) =>
 44→        m.id === id ? { ...m, content: m.content + text } : m
 45→      )
 46→    );
 47→    textBufferRef.current = '';
 48→  }, []);
 49→
 50→  const sendMessage = useCallback(
 51→    async (text: string) => {
 52→      if (isStreaming) return;
 53→
 54→      const userMsg: ChatMessage = {
 55→        id: generateId(),
 56→        role: 'user',
 57→        content: text,
 58→      };
 59→
 60→      const assistantId = generateId();
 61→      assistantIdRef.current = assistantId;
 62→      const assistantMsg: ChatMessage = {
 63→        id: assistantId,
 64→        role: 'assistant',
 65→        content: '',
 66→        toolCalls: [],
 67→        isStreaming: true,
 68→      };
 69→
 70→      setMessages((prev) => [...prev, userMsg, assistantMsg]);
 71→      setIsStreaming(true);
 72→      textBufferRef.current = '';
 73→      segmentsRef.current = [];
 74→      currentTextRef.current = '';
 75→      phaseRef.current = 'thinking';
 76→
 77→      // Build conversation history from current messages for resume fallback
 78→      const history = messages
 79→        .filter((m) => m.role === 'user' || m.role === 'assistant')
 80→        .map((m) => ({ role: m.role, content: m.content }));
 81→
 82→      // If there's pending history from a delete, start a new Langfuse session with that context
 83→      const pendingHistory = pendingHistoryRef.current;
 84→      pendingHistoryRef.current = null;
 85→      const langfuseSessionId = pendingHistory ? generateUUID() : null;
 86→
 87→      const controller = new AbortController();
 88→      abortRef.current = controller;
 89→
 90→      await runAgentLoop(
 91→        text,
 92→        sessionIdRef.current,
 93→        langfuseSessionId,
 94→        pendingHistory ?? (history.length > 0 ? history : null),
 95→        {
 96→          onTextChunk: (chunk) => {
 97→            textBufferRef.current += chunk;
 98→            if (!flushTimerRef.current) {
 99→              flushTimerRef.current = setTimeout(() => {
100→                flushText();
101→                flushTimerRef.current = null;
102→              }, 50);
103→            }
104→          },
105→          onThinkingDone: () => {
106→            // Extended thinking just ended and a text block is starting.
107→            // Create a thinking segment from accumulated thinking text.
108→            if (flushTimerRef.current) {
109→              clearTimeout(flushTimerRef.current);
110→              flushTimerRef.current = null;
111→            }
112→            flushText();
113→            if (currentTextRef.current.trim()) {
114→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
115→              currentTextRef.current = '';
116→            }
117→            phaseRef.current = 'answer';
118→            setMessages((prev) =>
119→              prev.map((m) =>
120→                m.id === assistantId
121→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
122→                  : m
123→              )
124→            );
125→          },
126→          onToolCall: (pending: ToolCallResult) => {
127→            if (flushTimerRef.current) {
128→              clearTimeout(flushTimerRef.current);
129→              flushTimerRef.current = null;
130→            }
131→            flushText();
132→            if (currentTextRef.current.trim()) {
133→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
134→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
135→              currentTextRef.current = '';
136→            }
137→            // Add a pending tool segment so the input is shown immediately
138→            segmentsRef.current.push({
139→              type: 'tool',
140→              toolResult: pending,
141→            });
142→            setMessages((prev) =>
143→              prev.map((m) =>
144→                m.id === assistantId
145→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
146→                  : m
147→              )
148→            );
149→          },
150→          onToolResult: (result: ToolCallResult) => {
151→            // Merge result into pending tool segment (keep input info, add output)
152→            const pendingIdx = segmentsRef.current.findIndex(
153→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
154→            );
155→            if (pendingIdx !== -1) {
156→              const pending = segmentsRef.current[pendingIdx].toolResult!;
157→              segmentsRef.current[pendingIdx] = {
158→                type: 'tool',
159→                toolResult: {
160→                  ...pending,
161→                  ...result,
162→                  sql: result.sql || pending.sql,
163→                  toolName: result.toolName || pending.toolName,
164→                  command: result.command || pending.command,
165→                  toolInput: result.toolInput || pending.toolInput,
166→                },
167→              };
168→            } else {
169→              segmentsRef.current.push({ type: 'tool', toolResult: result });
170→            }
171→            setMessages((prev) =>
172→              prev.map((m) =>
173→                m.id === assistantId
174→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
175→                  : m
176→              )
177→            );
178→            refreshTables();
179→          },
180→          onSubagentStart: (data) => {
181→            if (flushTimerRef.current) {
182→              clearTimeout(flushTimerRef.current);
183→              flushTimerRef.current = null;
184→            }
185→            flushText();
186→            if (currentTextRef.current.trim()) {
187→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
188→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
189→              currentTextRef.current = '';
190→            }
191→            segmentsRef.current.push({
192→              type: 'subagent_start',
193→              subagentId: data.id,
194→              subagentName: data.name,
195→              text: data.prompt,
196→            });
197→            setMessages((prev) =>
198→              prev.map((m) =>
199→                m.id === assistantId
200→                  ? { ...m, segments: [...segmentsRef.current] }
201→                  : m
202→              )
203→            );
204→          },
205→          onSubagentEnd: (data) => {
206→            segmentsRef.current.push({
207→              type: 'subagent_end',
208→              subagentId: data.id,
209→              subagentName: data.name,
210→              chart_spec: data.chart_spec,
211→              text: data.result,
212→            });
213→            setMessages((prev) =>
214→              prev.map((m) =>
215→                m.id === assistantId
216→                  ? { ...m, segments: [...segmentsRef.current] }
217→                  : m
218→              )
219→            );
220→          },
221→          onDone: (newSessionId) => {
222→            if (newSessionId) sessionIdRef.current = newSessionId;
223→            if (flushTimerRef.current) {
224→              clearTimeout(flushTimerRef.current);
225→              flushTimerRef.current = null;
226→            }
227→            flushText();
228→            if (currentTextRef.current.trim()) {
229→              segmentsRef.current.push({
230→                type: 'answer',
231→                text: currentTextRef.current,
232→              });
233→              currentTextRef.current = '';
234→            }
235→            setMessages((prev) =>
236→              prev.map((m) =>
237→                m.id === assistantId
238→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
239→                  : m
240→              )
241→            );
242→            setIsStreaming(false);
243→            abortRef.current = null;
244→          },
245→          onError: (error) => {
246→            if (flushTimerRef.current) {
247→              clearTimeout(flushTimerRef.current);
248→              flushTimerRef.current = null;
249→            }
250→            flushText();
251→            if (currentTextRef.current.trim()) {
252→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
253→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
254→              currentTextRef.current = '';
255→            }
256→            segmentsRef.current.push({ type: 'error', errorMessage: error });
257→            setMessages((prev) =>
258→              prev.map((m) =>
259→                m.id === assistantId
260→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
261→                  : m
262→              )
263→            );
264→            setIsStreaming(false);
265→            abortRef.current = null;
266→          },
267→          onUserQuestion: (data) => {
268→            if (flushTimerRef.current) {
269→              clearTimeout(flushTimerRef.current);
270→              flushTimerRef.current = null;
271→            }
272→            flushText();
273→            if (currentTextRef.current.trim()) {
274→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
275→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
276→              currentTextRef.current = '';
277→            }
278→            segmentsRef.current.push({
279→              type: 'user_question',
280→              questionData: data,
281→            });
282→            setMessages((prev) =>
283→              prev.map((m) =>
284→                m.id === assistantId
285→                  ? { ...m, segments: [...segmentsRef.current] }
286→                  : m
287→              )
288→            );
289→          },
290→        },
291→        controller.signal,
292→        userSessionId,
293→      );
294→    },
295→    [isStreaming, flushText, refreshTables, userSessionId]
296→  );
297→
298→  const editMessage = useCallback(
299→    async (messageIndex: number, newContent: string) => {
300→      if (isStreaming) return;
301→
302→      // Build conversation history from messages before the edit point
303→      const conversationHistory: { role: string; content: string }[] = [];
304→      for (let i = 0; i < messageIndex; i++) {
305→        const msg = messages[i];
306→        if (msg.role === 'user' || msg.role === 'assistant') {
307→          conversationHistory.push({ role: msg.role, content: msg.content });
308→        }
309→      }
310→
311→      const assistantId = generateId();
312→      assistantIdRef.current = assistantId;
313→
314→      const userMsg: ChatMessage = {
315→        id: generateId(),
316→        role: 'user',
317→        content: newContent,
318→      };
319→      const assistantMsg: ChatMessage = {
320→        id: assistantId,
321→        role: 'assistant',
322→        content: '',
323→        toolCalls: [],
324→        isStreaming: true,
325→      };
326→
327→      setMessages((prev) => [...prev.slice(0, messageIndex), userMsg, assistantMsg]);
328→      setIsStreaming(true);
329→      textBufferRef.current = '';
330→      segmentsRef.current = [];
331→      currentTextRef.current = '';
332→      phaseRef.current = 'thinking';
333→
334→      const controller = new AbortController();
335→      abortRef.current = controller;
336→
337→      await runAgentEditLoop(
338→        newContent,
339→        conversationHistory,
340→        generateUUID(),
341→        {
342→          onTextChunk: (chunk) => {
343→            textBufferRef.current += chunk;
344→            if (!flushTimerRef.current) {
345→              flushTimerRef.current = setTimeout(() => {
346→                flushText();
347→                flushTimerRef.current = null;
348→              }, 50);
349→            }
350→          },
351→          onThinkingDone: () => {
352→            if (flushTimerRef.current) {
353→              clearTimeout(flushTimerRef.current);
354→              flushTimerRef.current = null;
355→            }
356→            flushText();
357→            if (currentTextRef.current.trim()) {
358→              segmentsRef.current.push({ type: 'thinking', text: currentTextRef.current });
359→              currentTextRef.current = '';
360→            }
361→            phaseRef.current = 'answer';
362→            setMessages((prev) =>
363→              prev.map((m) =>
364→                m.id === assistantId
365→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
366→                  : m
367→              )
368→            );
369→          },
370→          onToolCall: (pending: ToolCallResult) => {
371→            if (flushTimerRef.current) {
372→              clearTimeout(flushTimerRef.current);
373→              flushTimerRef.current = null;
374→            }
375→            flushText();
376→            if (currentTextRef.current.trim()) {
377→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
378→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
379→              currentTextRef.current = '';
380→            }
381→            segmentsRef.current.push({ type: 'tool', toolResult: pending });
382→            setMessages((prev) =>
383→              prev.map((m) =>
384→                m.id === assistantId
385→                  ? { ...m, currentPhase: 'answer', segments: [...segmentsRef.current] }
386→                  : m
387→              )
388→            );
389→          },
390→          onToolResult: (result: ToolCallResult) => {
391→            const pendingIdx = segmentsRef.current.findIndex(
392→              (s) => s.type === 'tool' && s.toolResult?.toolCallId === result.toolCallId
393→            );
394→            if (pendingIdx !== -1) {
395→              const pending = segmentsRef.current[pendingIdx].toolResult!;
396→              segmentsRef.current[pendingIdx] = {
397→                type: 'tool',
398→                toolResult: {
399→                  ...pending,
400→                  ...result,
401→                  sql: result.sql || pending.sql,
402→                  toolName: result.toolName || pending.toolName,
403→                  command: result.command || pending.command,
404→                  toolInput: result.toolInput || pending.toolInput,
405→                },
406→              };
407→            } else {
408→              segmentsRef.current.push({ type: 'tool', toolResult: result });
409→            }
410→            setMessages((prev) =>
411→              prev.map((m) =>
412→                m.id === assistantId
413→                  ? { ...m, toolCalls: [...(m.toolCalls || []), result], segments: [...segmentsRef.current] }
414→                  : m
415→              )
416→            );
417→            refreshTables();
418→          },
419→          onSubagentStart: (data) => {
420→            if (flushTimerRef.current) {
421→              clearTimeout(flushTimerRef.current);
422→              flushTimerRef.current = null;
423→            }
424→            flushText();
425→            if (currentTextRef.current.trim()) {
426→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
427→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
428→              currentTextRef.current = '';
429→            }
430→            segmentsRef.current.push({
431→              type: 'subagent_start',
432→              subagentId: data.id,
433→              subagentName: data.name,
434→              text: data.prompt,
435→            });
436→            setMessages((prev) =>
437→              prev.map((m) =>
438→                m.id === assistantId
439→                  ? { ...m, segments: [...segmentsRef.current] }
440→                  : m
441→              )
442→            );
443→          },
444→          onSubagentEnd: (data) => {
445→            segmentsRef.current.push({
446→              type: 'subagent_end',
447→              subagentId: data.id,
448→              subagentName: data.name,
449→              chart_spec: data.chart_spec,
450→              text: data.result,
451→            });
452→            setMessages((prev) =>
453→              prev.map((m) =>
454→                m.id === assistantId
455→                  ? { ...m, segments: [...segmentsRef.current] }
456→                  : m
457→              )
458→            );
459→          },
460→          onDone: (newSessionId) => {
461→            if (newSessionId) sessionIdRef.current = newSessionId;
462→            if (flushTimerRef.current) {
463→              clearTimeout(flushTimerRef.current);
464→              flushTimerRef.current = null;
465→            }
466→            flushText();
467→            if (currentTextRef.current.trim()) {
468→              segmentsRef.current.push({ type: 'answer', text: currentTextRef.current });
469→              currentTextRef.current = '';
470→            }
471→            setMessages((prev) =>
472→              prev.map((m) =>
473→                m.id === assistantId
474→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
475→                  : m
476→              )
477→            );
478→            setIsStreaming(false);
479→            abortRef.current = null;
480→          },
481→          onError: (error) => {
482→            if (flushTimerRef.current) {
483→              clearTimeout(flushTimerRef.current);
484→              flushTimerRef.current = null;
485→            }
486→            flushText();
487→            if (currentTextRef.current.trim()) {
488→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
489→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
490→              currentTextRef.current = '';
491→            }
492→            segmentsRef.current.push({ type: 'error', errorMessage: error });
493→            setMessages((prev) =>
494→              prev.map((m) =>
495→                m.id === assistantId
496→                  ? { ...m, isStreaming: false, currentPhase: undefined, segments: [...segmentsRef.current] }
497→                  : m
498→              )
499→            );
500→            setIsStreaming(false);
501→            abortRef.current = null;
502→          },
503→          onUserQuestion: (data) => {
504→            if (flushTimerRef.current) {
505→              clearTimeout(flushTimerRef.current);
506→              flushTimerRef.current = null;
507→            }
508→            flushText();
509→            if (currentTextRef.current.trim()) {
510→              const segType = phaseRef.current === 'answer' ? 'answer' : 'thinking';
511→              segmentsRef.current.push({ type: segType, text: currentTextRef.current });
512→              currentTextRef.current = '';
513→            }
514→            segmentsRef.current.push({
515→              type: 'user_question',
516→              questionData: data,
517→            });
518→            setMessages((prev) =>
519→              prev.map((m) =>
520→                m.id === assistantId
521→                  ? { ...m, segments: [...segmentsRef.current] }
522→                  : m
523→              )
524→            );
525→          },
526→        },
527→        controller.signal,
528→        userSessionId,
529→      );
530→    },
531→    [isStreaming, messages, flushText, refreshTables, userSessionId]
532→  );
533→
534→  const deleteMessage = useCallback(
535→    (messageIndex: number) => {
536→      if (isStreaming) return;
537→
538→      // Store remaining messages as history for Langfuse context on next send
539→      setMessages((prev) => {
540→        const remaining = prev.slice(0, messageIndex);
541→        pendingHistoryRef.current = remaining
542→          .filter((m) => m.role === 'user' || m.role === 'assistant')
543→          .map((m) => ({ role: m.role, content: m.content }));
544→        return remaining;
545→      });
546→
547→      // Clear session so next message starts fresh
548→      sessionIdRef.current = null;
549→    },
550→    [isStreaming]
551→  );
552→
553→  const respondToQuestion = useCallback(
554→    async (questionId: string, answers: string[], freeText?: string) => {
555→      // Update the segment to show the user's answer
556→      const segIdx = segmentsRef.current.findIndex(
557→        (s) => s.type === 'user_question' && s.questionData?.questionId === questionId
558→      );
559→      if (segIdx !== -1) {
560→        segmentsRef.current[segIdx] = {
561→          ...segmentsRef.current[segIdx],
562→          userAnswer: answers,
563→          userFreeText: freeText,
564→        };
565→        setMessages((prev) =>
566→          prev.map((m) =>
567→            m.id === assistantIdRef.current
568→              ? { ...m, segments: [...segmentsRef.current] }
569→              : m
570→          )
571→        );
572→      }
573→
574→      // POST to backend
575→      try {
576→        await fetch('/api/chat/respond', {
577→          method: 'POST',
578→          headers: {
579→            'Content-Type': 'application/json',
580→            ...(userSessionId ? { 'X-Session-ID': userSessionId } : {}),
581→          },
582→          body: JSON.stringify({
583→            question_id: questionId,
584→            answers,
585→            free_text: freeText || null,
586→          }),
587→        });
588→      } catch (e) {
589→        console.error('Failed to respond to question:', e);
590→      }
591→    },
592→    [userSessionId]
593→  );
594→
595→  const clearMessages = useCallback(() => {
596→    if (abortRef.current) {
597→      abortRef.current.abort();
598→    }
599→    setMessages([]);
600→    setIsStreaming(false);
601→    sessionIdRef.current = null;
602→    pendingHistoryRef.current = null;
603→  }, []);
604→
605→  return (
606→    <AgentContext.Provider
607→      value={{ messages, isStreaming, sendMessage, editMessage, deleteMessage, clearMessages, respondToQuestion }}
608→    >
609→      {children}
610→    </AgentContext.Provider>
611→  );
612→}
